// CSD_RATIONALE_BEGIN
// Root-cause analysis of the prior attempt:
//   (A) 28/49 examples had only TINY visible spans (median 1 token, e.g. <<n>>).
//       The model was using "<<" as a template-notation in its chain-of-thought
//       (e.g., "cost per unit = <<unit_price>>"). GenerateWithPrefixAndManagedSpan
//       reacted to each such "<<", entered constrained mode, and closed the span
//       at the first complete parse (a single variable name). The evaluator uses
//       the LAST visible span, but that was already a wrong single-variable answer.
//   (B) 5/49 examples had unterminated spans: the model opened "<<" near budget
//       exhaustion and the strategy ran out of steps without emitting ">>".
//
// New strategy:
//   Phase 0 – If we enter with an open span, close it within a small budget.
//   Phase 1 – Unconstrained generation for 87% of budget. We intentionally do
//              NOT enter constrained mode when the model writes "<<"; any
//              intermediate "<<expr>>" in the model's reasoning stays in generated
//              as plain tokens (the evaluator picks the LAST span, so this is safe).
//   Phase 2 – Forcibly open a fresh constrained span via OpenConstrainedSpan.
//              The forced "<<" is always at the END of all reasoning text.
//   Phase 3 – CloseSpanWithinBudget for the remaining budget. This helper
//              generates forward, tracks the LONGEST prefix that parses as
//              complete (not just the first), and emits ">>" there. This prevents
//              the "<<n>>" collapse and reliably closes within budget.
//
// Guidance change: explicitly forbid "<<" and ">>" in reasoning text, and show
// an example of a full int(expr) form to anchor the model's generation.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initialization: copied from precondition; holds by assumption.
//   Phase 0 (CloseSpanWithinBudget): its postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//   Phase 1 loop body: the loop condition requires !insideConstrainedOut, so
//     insideConstrainedOut is false throughout every iteration; the implication
//     is vacuously true. We never assign insideConstrainedOut := true inside
//     the loop, so this cannot become false unexpectedly.
//   Phase 2 (OpenConstrainedSpan): sets insideConstrainedOut := true and
//     currentConstrainedOut := []. parser.IsValidPrefix([]) holds by the
//     method precondition `parser.IsValidPrefix([])`. ✓
//   Phase 3 (CloseSpanWithinBudget): postcondition guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
// Invariant 2 – progress:
//   |generated| <= |generatedPrefix| + steps, and cost <= maxSteps.
//
//   Initialization: |generated| = |generatedPrefix|, steps = 0. ✓
//   Phase 0: CloseSpanWithinBudget guarantees |generatedOut| <= |generated| + ib.
//     After: |generated| <= |generatedPrefix| + ib = |generatedPrefix| + steps. ✓
//   Phase 1 loop: each iteration increments steps by 1 and appends at most one
//     token to generated (EOS path adds nothing). So after each iteration,
//     |generated| <= |generatedPrefix| + steps. Loop decreases on (pb - steps);
//     pb < maxSteps, so steps <= maxSteps throughout. ✓
//   Phase 2: steps increments by 1, generated grows by exactly 1 (the "<<" token).
//     |generated| <= |generatedPrefix| + steps. ✓
//   Phase 3: CloseSpanWithinBudget guarantees |generatedOut| <= |old_generated| + rb.
//     Setting steps := maxSteps: |generated| <= |generatedPrefix| + maxSteps. ✓
//     cost = steps = maxSteps. ✓
//   When maxSteps > 0: either phase 0 consumes steps > 0, or phase 1 takes at
//     least one unconstrained step, or phase 2 opens a span consuming 1 step.
//     In all paths, steps >= 1 when maxSteps > 0, so cost > 0. ✓
//   Tokens consumed by CloseSpanWithinBudget that are not appended visibly
//     (EOS, dead-end resamples) still count against the budget and are bounded
//     by ib / rb, so the length bound is preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps > 0 {
  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. Show all your work clearly. " +
    "CRITICAL RULE: Do NOT write << or >> anywhere in your reasoning or intermediate calculations. " +
    "Only at the very last line of your response, write the final symbolic answer in this exact format: " +
    "<<int(expr)>> " +
    "where expr is a single arithmetic expression using only: " +
    "variable names from the problem (no curly braces {}), integers, +, -, *, /, //, %, (, ), int(). " +
    "Always wrap integer results in int(). No LaTeX, no {braces}, no ** operator. " +
    "Keep the expression concise. Example: <<int(n * price - quantity * discount)>>");

  var steps: nat := 0;

  // Phase 0: Close any initially open constrained span
  if insideConstrainedOut && steps < maxSteps {
    var ib: nat := 15;
    if ib > maxSteps - steps { ib := maxSteps - steps; }
    var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, ib
    );
    generated := cg0;
    insideConstrainedOut := ci0;
    currentConstrainedOut := cc0;
    steps := steps + ib;
  }

  // Phase 1: Free unconstrained generation; intentionally ignore any "<<" emitted
  var pb: nat := (maxSteps * 87) / 100;
  if pb >= maxSteps { pb := maxSteps - 1; }

  while steps < pb && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases pb - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    // Intentionally NOT entering constrained mode here; any "<<" is plain text
  }

  // Phase 2: Force open a fresh constrained span for the final answer
  if !insideConstrainedOut && steps < maxSteps {
    var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
    steps := steps + 1;
  }

  // Phase 3: Generate full expression and reliably close within remaining budget.
  // CloseSpanWithinBudget tracks the LONGEST complete parse prefix (not the first),
  // preventing early closure at single-variable expressions like "n".
  if insideConstrainedOut && steps < maxSteps {
    var rb: nat := maxSteps - steps;
    var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, rb
    );
    generated := cg3;
    insideConstrainedOut := ci3;
    currentConstrainedOut := cc3;
    steps := maxSteps;
  }

  cost := steps;
}

